#!/usr/bin/env python3
"""
topup_block9_to_580_words.py
Expands each part in Days 41 to 45 so that `say` has >= 585 words per part.
"""
import json

def get_word_count(part):
    return sum(len(s.split()) for s in part['say'])

def ensure_part_words(day_dict, part_idx, paragraphs, min_target=585):
    part = day_dict['parts'][part_idx]
    wc = get_word_count(part)
    for p in paragraphs:
        if wc >= min_target:
            break
        part['say'].append(p)
        wc = get_word_count(part)
    return wc

print("Loading Days 41-45 JSON files...")
days = {}
for d in range(41, 46):
    with open(f"scripts/iot_edge_day{d}.json", "r", encoding="utf-8") as f:
        days[d] = json.load(f)

